"""Build the source-backed visual model guide without training or deployment."""
from pathlib import Path
import json,html,os,hashlib,csv
from datetime import datetime,timezone
import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from scripts.build_model_register import read_sources
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'project_guide/models'
def read(p):return json.loads((ROOT/p).read_text(encoding='utf-8'))
def href(p):return os.path.relpath(ROOT/p,OUT).replace('\\','/')
def main():
 OUT.mkdir(parents=True,exist_ok=True)
 prob=read('outputs/model_validation/20261102_return_probability/results.json');review=read('outputs/model_validation/20261102_claude_independent_review/audit_results.json');active=read('config/cp2_model_current.json');planning=read('webapp/models/planning_v1.json');repeat=read('webapp/models/repeat90_v1.json')
 records,sources,excluded,features=read_sources()
 for name,rows in [('All_Saved_Results.csv',records),('Source_Index.csv',sources),('Excluded_Runs.csv',excluded),('Declared_Input_Lists.csv',features)]:pd.DataFrame(rows).to_csv(OUT/name,index=False)
 # Scientific figures are static, standalone and reproducible.
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False})
 fig,ax=plt.subplots(figsize=(9,4.3));labels=['Uncalibrated\nforest','Existing\ncalibration','New probability\ncandidate','Same risk\nfor everyone'];vals=[r['brier'] for r in prob['metrics']]
 bars=ax.barh(labels,vals,color=['#b8c1d4','#1f4fe0','#8b5cf6','#83909f']);ax.invert_yaxis();ax.set_xlim(0,.14);ax.set_xlabel('Probability error (Brier score): lower is better');ax.set_title('Same 2,075 historical services · 184 recorded returns',loc='left',pad=16)
 for bar,v in zip(bars,vals):ax.text(v+.002,bar.get_y()+bar.get_height()/2,f'{v:.4f}',va='center')
 fig.tight_layout();fig.savefig(OUT/'probability_error.png',dpi=160);plt.close(fig)
 fig,ax=plt.subplots(figsize=(7,5));ax.plot([0,1],[0,1],ls='--',color='#99a3b4',label='Perfect agreement')
 for name,col in [('Existing calibration','#1f4fe0'),('New probability candidate','#8b5cf6')]:
  bins=[r for r in prob['bands'] if r['model']==name];ax.plot([r['predicted'] for r in bins],[r['observed'] for r in bins],marker='o',lw=2,color=col,label=name)
  for r in bins:
   if r['services']<30:ax.annotate(f"Small group: n={r['services']}",(r['predicted'],r['observed']),xytext=(8,-18),textcoords='offset points',fontsize=8,color=col)
 ax.set(xlim=(0,.65),ylim=(0,.65),xlabel='Average predicted probability',ylabel='Recorded return rate',title='Do predicted risks match what happened?');ax.legend(loc='upper left',frameon=False);fig.tight_layout();fig.savefig(OUT/'probability_reliability.png',dpi=160);plt.close(fig)
 families=[]
 def add(name,status,question,inputs,result,meaning,source):families.append(dict(name=name,status=status,question=question,inputs=inputs,result=result,meaning=meaning,source=href(source)))
 add('Original 30-day pest-return model','Frozen collector configuration','Will a matched service have a recorded corrective return within 30 days?','93 inputs: service/package, pest, previous visits and returns, location and environmental features. Extra Trees, 300 trees.','100-service historical test: 5 positives; 94% accuracy, 40% precision, 40% recall. Always-no-return: 95%.','The later frozen refit trained on 5,695 services. Training rows are not a test. Configuration is verified; current cloud health was not checked for this guide.','config/cp2_model_current.json')
 add('Larger historical reference','Research reference','Same 30-day question, evaluated on a larger historical population.','93 inputs; same Extra Trees settings. Separate training 1,506, validation 1,177, assessment 2,075.','184 positives; 77.7% accuracy, 23.0% precision, 64.7% recall. Existing calibrated Brier 0.0735.','Different fit, records and threshold from the 100-service result. This reference supports the new probability experiment; it does not replace the frozen collector.','outputs/model_validation/20261017_larger_frozen_test/results.json')
 add('30-day probability comparison','New experiment; not promoted','How likely is a recorded return within 30 days?','Same fixed 93-input classifier; raw scores, sigmoid, logit, beta and isotonic calibration.','Validation chose isotonic. Assessment Brier 0.0740 vs existing 0.0735; constant risk 0.0808.','Lower is better. The new candidate beats constant risk but does not beat existing calibration. Keep existing method; no deployment or probability guarantee.','outputs/model_validation/20261102_return_probability/results.json')
 add("Claude’s property warranty risk",'Website research candidate; needs revision','After a non-warranty appointment, will the same rounded-coordinate group have a warranty signal within 30 days?','8 visit-history inputs; 200 Extra Trees plus Platt calibration.','1,104 historical windows, 107 positives; AUC 0.767. At 20% threshold: 81.4% accuracy, 24.7% precision, 44.9% recall.','Not comparable directly with the original test. Timing corrections retain ranking; exact property identity and paid-service labels are not established. Its saved forward test starts before prediction creation and is not valid as claimed.','outputs/model_validation/20261102_claude_independent_review/Review.md')
 add('Pest-specific specialists','Research; not promoted','Does a separate pest-group model predict returns better?','Original 93 inputs and unchanged Extra Trees pipeline, fitted separately for supported pest groups.','Cockroach-only: 1,428 assessment services; 74.4% accuracy, 24.9% precision, 68.2% recall. General reference on same group: 72.6%, 23.8%, 70.1%.','Ranking barely changes. Other individual pests have too few positive training cases. Anchor pest is known; outcome is not necessarily the same pest.','outputs/model_validation/20261102_pest_specialists/Results_Explained.md')
 for m in planning['models']:
  add(m['title'].replace('·','—'),'Packaged planning candidate',m['title'],f"{m['inputs']} inputs; {m['algorithm']}. Calendar/history and booking context; exact contract in linked model.",f"Historical MAE {m['mae']:.1f} vs baseline {m['baseline_mae']:.1f}; {m['test_windows']} test windows.",'MAE is average absolute prediction error, in bookings or appointment hours. These are not pest-recurrence models. Packaged does not prove current cloud operation.','webapp/models/planning_v1.json')
 ev=repeat['evaluation'];add('Repeat purchase within 90 days','Packaged experimental ranking','Which first-time customers might buy another programme?','Initial sale, purchase season and saved customer/package context; exact input list in the model.','557 customers, 19 positives; AUC 0.761, AP 0.094.','Predicts another purchase, not pest recurrence. Scores are explicitly marked uncalibrated. It does not prove marketing causes additional purchases.','webapp/models/repeat90_v1.json')
 add('60-day return after final service','Research evidence only','Will a residential programme have a recorded return within 60 days after its final paid service?','Service inputs; logistic regression; multiple historical folds.','937 windows, 319 positives; 49.1% accuracy, 39.4% precision, 92.5% recall.','92.5% is recall, not accuracy. Different question and population from the 30-day model. Current-source rebuild and a new future evaluation are required.','webapp/models/return_research_best.json')
 add('Quote, renewal and other targets','Historical studies','Commercial quotation, repeat-purchase timing, programme-end purchases, weekly sales and operational forecasts.','Each study has its own data, target, inputs, partition and baseline.','See study files and the searchable result index; there is no meaningful single accuracy across these questions.','Small property-size coverage limits quotation work. Some newer weekly-count searches did not beat a moving average. A saved result is not an operational model.','planning/CP2_OPERATIONAL_MODEL_SEARCH_20261102.md')
 (OUT/'model_families.json').write_text(json.dumps(families,indent=2),encoding='utf-8')
 e=html.escape
 cards=''.join(f'<article class="model"><div class="status">{e(m["status"])}</div><h3>{e(m["name"])}</h3><p class="question">{e(m["question"])}</p><dl><dt>Inputs and method</dt><dd>{e(m["inputs"])}</dd><dt>Saved results</dt><dd>{e(m["result"])}</dd><dt>What it means</dt><dd>{e(m["meaning"])}</dd></dl><a href="{e(m["source"])}">Open evidence</a></article>' for m in families)
 studies=[]
 for d in sorted((ROOT/'outputs/model_validation').iterdir()):
  if not d.is_dir():continue
  files=[p for p in d.rglob('*') if p.is_file() and p.suffix in {'.json','.csv','.md','.html','.ipynb'} and any(s in p.name.lower() for s in ('result','comparison','review','explained','protocol')) and not any(s in p.name.lower() for s in ('private','predictions','identities','dataset','freeze_'))]
  if files:studies.append('<details><summary>'+e(d.name.replace('_',' '))+f' <span>{len(files)} evidence files</span></summary><ul>'+''.join(f'<li><a href="{e(href(p.relative_to(ROOT)))}">{e(p.relative_to(d).as_posix())}</a></li>' for p in files)+'</ul></details>')
 clean=[]
 for r in records:
  row={k:(None if isinstance(v,float) and not np.isfinite(v) else v) for k,v in r.items()};clean.append(row)
 payload=json.dumps(clean,ensure_ascii=True,default=str).replace('<','\\u003c')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nomobug | Model guide</title><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f3f5f9;color:#182033;font:15px/1.65 system-ui}aside{position:fixed;inset:0 auto 0 0;width:224px;background:#101319;color:#fff;padding:30px 22px}aside b{letter-spacing:4px}aside a{display:block;color:#bfc8dc;text-decoration:none;margin:20px 0}main{margin-left:224px;padding:42px;max-width:1500px}h1{font-size:44px;line-height:1.15;letter-spacing:-1.5px}h2{font-size:28px;margin-top:42px}h3{font-size:22px;line-height:1.3}a{color:#1f4fe0}.hero{background:#1f4fe0;color:white;padding:30px;margin:26px 0}.hero b{font-size:23px}.strip{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:22px 0}.strip div{border-top:3px solid #1f4fe0;padding:12px;background:white}.strip b{font-size:24px;display:block}.note{background:#fff2d8;border-left:4px solid #d29225;padding:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.model{background:white;border:1px solid #dce2ed;padding:24px}.status{font-size:12px;font-weight:700;color:#1f4fe0}.question{font-size:17px}dt{font-size:12px;font-weight:700;color:#647089;margin-top:14px}dd{margin:2px 0 12px}img{max-width:100%;background:white}figure{margin:0;background:white;padding:16px}figcaption{font-size:13px;color:#536076}section{scroll-margin-top:18px}table{border-collapse:collapse;background:white;width:100%;font-size:12px}th,td{padding:12px;text-align:left;border-bottom:1px solid #e1e6ef;vertical-align:top;overflow-wrap:anywhere}th{background:#e7edf9}input,select,button{font:inherit;padding:10px;border:1px solid #cbd3e2;background:white;border-radius:4px}input{width:45%}.scroll{overflow:auto}details{background:white;padding:12px 18px;margin:8px 0}summary{cursor:pointer}summary span{float:right;color:#647089;font-size:12px}.muted{color:#647089}.flow{display:flex;gap:12px;align-items:stretch;margin:22px 0}.flow div{flex:1;background:#e7edf9;padding:18px;border-top:3px solid #1f4fe0}@media(max-width:900px){aside{position:static;width:auto}aside a{display:inline-block;margin:10px}main{margin:0;padding:22px}.grid,.strip{grid-template-columns:1fr}.flow{flex-direction:column}h1{font-size:34px}}</style><aside><b>NOMOBUG</b><p>Model guide<br>2 November 2026</p><a href="#current">What is used now</a><a href="#probability">Probability test</a><a href="#models">Model families</a><a href="#results">All saved results</a><a href="#studies">Study folders</a><a href="../..//FILE_GUIDE.html">Project files</a></aside><main><p class="muted">CAPSTONE PROJECT / PREDICTION MODELS</p><h1>What we tested.<br>What the evidence supports.</h1><p>One guide to prediction questions, inputs, results and model status. All figures here are historical unless explicitly labelled otherwise.</p><section id="current"><h2>What is used now?</h2><div class="hero"><b>The original 30-day model remains the frozen collector model.</b><p>The new probability method, pest specialists and Claude’s property model have not replaced it.</p></div><div class="strip"><div><b>93 inputs</b>Original Extra Trees model</div><div><b>100 services</b>Small historical assessment: 5 positives</div><div><b>94% / 40% / 40%</b>Accuracy / precision / recall</div></div><p class="note">The always-no-return baseline has 95% accuracy on that small test. A model’s configuration, a file packaged in the website, and a verified live deployment are three different things. This guide reads local artifacts; it does not certify current cloud collection health. The redesigned website is deployed; experimental model limitations remain.</p><div class="flow"><div><b>Frozen collection</b><br>Original v5 and its existing prediction ledger stay unchanged.</div><div><b>Website tools</b><br>Packaged planning and repeat-purchase candidates; separate questions and limitations.</div><div><b>New research</b><br>Probability calibration, pest specialists and Claude’s risk candidate need their own acceptance.</div></div></section><section id="probability"><h2>Can we give a useful probability?</h2><p>Instead of only “yes” or “no”, estimate the chance of a recorded return in 30 days. A 20% risk is useful only if similar predictions correspond to roughly 20 returns per 100 services over time. It is not a guarantee about one customer.</p><div class="strip"><div><b>1,506</b>Classifier training services</div><div><b>555 + 405</b>Calibration fitting + method validation</div><div><b>2,075</b>Historical assessment; 184 positives</div></div><p>We fixed the classifier and tested five probability methods. Earlier validation data fitted each mapping; later validation chose isotonic. Property/programme separation and outcome gaps were retained. This historical assessment has been examined before.</p><div class="grid"><figure><img src="probability_error.png" alt="Probability error comparison on the same historical assessment"><figcaption>Existing calibration has the lowest error. New candidate 0.0740; existing 0.0735; constant risk 0.0808. Lower is better.</figcaption></figure><figure><img src="probability_reliability.png" alt="Predicted probability versus observed return rate"><figcaption>Closer to the dashed line is better. Points group similar risks; small groups are uncertain. These are descriptive checks, not guaranteed customer probabilities.</figcaption></figure></div><p class="note"><b>Decision: keep the existing calibration.</b> The new candidate beats a constant risk but does not improve the existing method. Calibration alone does not create new predictive information. No weights or thresholds in the frozen model were changed.</p><p><a href="'''+e(href('outputs/model_validation/20261102_return_probability/protocol.json'))+'''">Partition and selection protocol</a> · <a href="'''+e(href('outputs/model_validation/20261102_return_probability/probability_metrics.csv'))+'''">Exact metrics</a> · <a href="'''+e(href('outputs/model_validation/20261102_return_probability/risk_bands.csv'))+'''">Risk groups</a></p></section><section id="models"><h2>The model families</h2><p>Compare models only when the question, service population, dates and evaluation method match. AUC is ranking quality, Brier is probability error, MAE is forecast error, and accuracy is a thresholded yes/no result.</p><div class="grid">'''+cards+'''</div></section><section id="results"><h2>All located saved results</h2><p>Search the recorded variants, folds, thresholds and studies. Rows are <b>not</b> a count of independent trained models, and the highest percentage is not an overall winner. Source paths and context are retained.</p><input id="query" placeholder="Search pest, rain, age, logistic, forecast…" aria-label="Search saved results"><select id="study" aria-label="Study filter"><option value="">All studies</option></select><p id="count"></p><div class="scroll"><table id="registry"></table></div><p><button id="prev">Previous</button> <button id="next">Next</button> · <a href="All_Saved_Results.csv">Download full CSV</a> · <a href="Declared_Input_Lists.csv">Recorded input definitions</a> · <a href="Excluded_Runs.csv">Excluded source records</a></p></section><section id="studies"><h2>Study folders and evidence</h2><p>Dated records are preserved. A folder can contain unsuccessful or superseded experiments. Raw customer records and credentials are not included in this guide.</p>'''+''.join(studies)+'''</section></main><script>const data='''+payload+''';let page=0;const q=document.getElementById('query'),s=document.getElementById('study');[...new Set(data.map(r=>r.Study))].sort().forEach(v=>{let o=document.createElement('option');o.value=v;o.textContent=v;s.append(o)});function draw(){let rows=data.filter(r=>(!s.value||r.Study===s.value)&&JSON.stringify(r).toLowerCase().includes(q.value.toLowerCase()));page=Math.max(0,Math.min(page,Math.ceil(rows.length/40)-1));let t=document.getElementById('registry');t.replaceChildren();let cols=['Study','Candidate','Accuracy %','Precision %','Recall %','AP','Brier','MAE','Inputs / context','Source','Location in source'];let h=document.createElement('tr');cols.forEach(c=>{let th=document.createElement('th');th.textContent=c;h.append(th)});t.append(h);rows.slice(page*40,(page+1)*40).forEach(r=>{let tr=document.createElement('tr');cols.forEach(c=>{let td=document.createElement('td');td.textContent=typeof r[c]==='number'?r[c].toFixed(4):r[c]??'';tr.append(td)});t.append(tr)});document.getElementById('count').textContent=rows.length+' saved metric rows · page '+(page+1)+' / '+Math.max(1,Math.ceil(rows.length/40))}q.oninput=s.onchange=()=>{page=0;draw()};document.getElementById('prev').onclick=()=>{page--;draw()};document.getElementById('next').onclick=()=>{page++;draw()};draw();</script></html>'''
 (OUT/'index.html').write_text(page,encoding='utf-8')
 (OUT/'README.md').write_text('# Model guide\n\nOpen index.html. It explains current model pointers, local candidates, probability calibration and the recorded experiment index. Source metrics and study links retain their original populations. No notebook execution, model fitting or deployment occurs when rebuilding this guide.\n\nBuild: python -m scripts.build_visual_model_guide\n',encoding='utf-8')
 (OUT/'manifest.json').write_text(json.dumps({'built_at_utc':datetime.now(timezone.utc).isoformat(),'family_cards':len(families),'saved_metric_rows':len(records),'source_files':len(sources),'excluded_files':len(excluded),'current_pointer_sha256':hashlib.sha256((ROOT/'config/cp2_model_current.json').read_bytes()).hexdigest(),'cloud_health_checked':False,'new_candidate_deployed':False},indent=2),encoding='utf-8')
 print(json.dumps({'guide':str(OUT/'index.html'),'families':len(families),'saved_metric_rows':len(records),'sources':len(sources)}))
if __name__=='__main__':main()
